<script setup lang="ts">
import { computed, ref } from 'vue'
import { onShow } from '@dcloudio/uni-app'
import AppPage from '../../components/AppPage.vue'
import Icon from '../../components/Icon.vue'
import DateStrip from '../../components/DateStrip.vue'
import NutrientBars from '../../components/NutrientBars.vue'
import PhotoThumb from '../../components/PhotoThumb.vue'
import { useHealthStore } from '../../stores/health'
import { dateKey, shiftDate } from '../../domain/dates'
import { mealKeys, mealNames } from '../../domain/types'
import type { Meal } from '../../domain/types'
import { portion, total } from '../../domain/nutrition'
import { confirm, display, navigate, toast } from '../../utils/ui'
const store=useHealthStore(),date=ref(dateKey())
onShow(()=>store.hydrate())
const entries=computed(()=>store.data.meals.filter(x=>x.date===date.value)),totals=computed(()=>total(entries.value)),marks=computed(()=>[...new Set(store.data.meals.map(x=>x.date))])
const meals=computed(()=>mealKeys.map(key=>({key,name:mealNames[key],entries:entries.value.filter(x=>x.meal===key),kcal:total(entries.value.filter(x=>x.meal===key)).kcal})))
function add(meal?:Meal){navigate('food',`date=${date.value}${meal?'&meal='+meal:''}`)}
async function copy(){const source=store.data.meals.filter(x=>x.date===shiftDate(date.value,-1));if(!source.length){toast('前一天还没有饮食记录');return}const ok=await confirm('复制前一天的饮食',`${date.value} 将新增 ${source.length} 项食物${entries.value.length?'，当天已有记录会保留，可能产生重复':''}。照片附件不会复制。`);if(ok&&store.copyYesterday(date.value))toast('已复制，可逐项调整份量')}
</script>
<template><AppPage tab="diet"><view class="row-between"><view><text class="eyebrow">EAT WELL, FEEL GOOD</text><text class="page-title">饮食日记</text></view><view class="diary-emblem"><Icon name="bowl" :size="27"/></view></view><DateStrip v-model="date" :marks="marks"/><view class="card diet-summary"><view class="row-between"><view><text class="summary-caption">{{ date===dateKey()?'今日':'当日' }}摄入</text><view class="summary-energy number">{{ Math.round(totals.kcal).toLocaleString() }}<text class="summary-target"> / {{ display(store.data.profile.targets.kcal) }} kcal</text></view></view><text class="pill">{{ entries.length }} 项食物</text></view><view class="progress-track mt-16"><view class="progress-fill" :style="{width:store.data.profile.targets.kcal?Math.min(100,totals.kcal/store.data.profile.targets.kcal*100)+'%':'0%'}"/></view><view class="divider"/><NutrientBars :values="totals" :targets="store.data.profile.targets"/></view><view class="diet-shortcuts"><button role="button" @click="navigate('food',`date=${date}&photo=1`)"><Icon name="camera" :size="16"/><text>拍照记录</text></button><button role="button" @click="navigate('food',`date=${date}&filter=favorites`)"><Icon name="star" :size="16"/><text>常吃食物</text></button><button role="button" @click="copy"><Icon name="copy" :size="16"/><text>复制昨天</text></button></view>
<view class="meal-list"><view v-for="meal in meals" :key="meal.key" class="meal-card"><view class="meal-heading row-between"><view class="row gap-8"><view class="meal-dot" :class="meal.key"/><text class="section-title">{{ meal.name }}</text><text class="meal-kcal">{{ Math.round(meal.kcal) }}<text> kcal</text></text></view><button role="button" class="meal-add" :aria-label="'添加'+meal.name" @click="add(meal.key)"><Icon name="plus" tone="white" :size="17"/></button></view><view v-if="meal.entries.length" class="meal-foods"><view v-for="entry in meal.entries" :key="entry.id" class="food-row" @click="navigate('food','id='+entry.id)"><PhotoThumb :art="entry.art" :photo="entry.photo"/><view class="grow"><text class="food-name">{{ entry.name }}</text><text class="food-sub">{{ entry.grams }} g · {{ Math.round(portion(entry.per100,entry.grams).kcal) }} kcal</text><text class="food-nutrition">蛋白质 {{ display(portion(entry.per100,entry.grams).protein,1) }} g</text></view><Icon name="arrow" tone="muted" :size="13"/></view></view><button role="button" v-else class="meal-empty" @click="add(meal.key)"><Icon name="plus" tone="muted" :size="17"/><text>还没记录，添加{{ meal.name }}</text></button></view></view><text class="footer-note">食物数据为参考值，实际以包装标签及烹饪方式为准。</text></AppPage></template>
<style scoped>.diary-emblem{width:47px;height:47px;border:1px solid #dce6d3;border-radius:17px;background:#e9efdf;display:flex;align-items:center;justify-content:center;transform:rotate(-5deg)}.diet-summary{padding:19px}.summary-caption{display:block;font-size:10px;color:var(--muted);margin-bottom:6px}.summary-energy{font-size:30px;font-weight:650}.summary-target{font-size:12px;font-weight:400;letter-spacing:0;color:var(--muted)}.diet-summary .progress-track{height:6px}.diet-shortcuts{display:flex;justify-content:space-between;gap:8px;margin:18px 0 25px}.diet-shortcuts button{flex:1;gap:5px;background:#edf1e6;border:1px solid #e2e8d8;border-radius:10px;padding:11px 4px;font-size:10px;white-space:nowrap;color:var(--green)}.meal-list{display:flex;flex-direction:column;gap:15px}.meal-card{border:1px solid var(--line);background:var(--white);border-radius:18px;padding:17px}.meal-heading .section-title{font-size:14px}.meal-kcal{font-size:14px;margin-left:3px;color:#63725d;font-weight:550}.meal-kcal text{font-size:9px;color:var(--muted);font-weight:400}.meal-dot{width:5px;height:14px;border-radius:4px;background:#d4b27d}.meal-dot.lunch{background:#63894e}.meal-dot.dinner{background:#829d92}.meal-dot.snack{background:#c9a1a0}.meal-add{width:27px;height:27px;border-radius:10px;background:var(--orange)}.meal-empty{display:flex;gap:7px;border:1px dashed #d9dfcf;border-radius:12px;padding:20px 10px;margin-top:14px;width:100%;font-size:11px;color:var(--muted);background:#f8f9f3}.food-row{display:flex;align-items:center;gap:12px;padding:14px 0;border-bottom:1px solid var(--line)}.food-row:last-child{border:0;padding-bottom:0}.food-row .photo-thumb{height:63px;width:63px;border-radius:12px}.food-name{font-size:13px;font-weight:550;display:block;margin-bottom:6px}.food-sub{font-size:11px;color:#718068;display:block}.food-nutrition{font-size:10px;color:var(--muted);display:block;margin-top:4px}</style>
